export { descriptionId, view } from "../select";
export type { SelectAttributes, ViewConfig } from "../select";

export {
  baseUiSelectChevronClassName,
  baseUiSelectControlClassName,
  baseUiSelectDescriptionClassName,
  baseUiSelectLabelClassName,
  baseUiSelectWrapperClassName,
} from "./view";

export {
  chevronClassName as baseUiSelectChevronClassName,
  descriptionClassName as baseUiSelectDescriptionClassName,
  labelClassName as baseUiSelectLabelClassName,
  selectClassName as baseUiSelectControlClassName,
  selectWrapperClassName as baseUiSelectWrapperClassName,
} from "../select/view";

import { describe, expect, test } from "vitest";

import * as Select from "./index";

describe("Base UI Select registry view", () => {
  test("reuses the Foldkit Select functional contract", () => {
    expect(Select.view).toBeTypeOf("function");
    expect(Select.descriptionId).toBeTypeOf("function");
    expect(Select.baseUiSelectControlClassName).toContain("rounded");
  });
});
